466	    @Test
467	    void sameTestItemWithDifferentTestKey_returns409_andHistoryKeepsStatusSnapshots() throws Exception {
468	        String batchKey = "BK-DUPITEM2-" + unique();
469	        createBatch(batchKey, List.of("t1", "t2"), 201);
